#!/usr/bin/env python3
# open_same_file_loop.py
# Opens the same file repeatedly and stores the file objects in a list so they
# stay referenced (and thus not GC-closed).

import sys
import time

path = sys.argv[1] if len(sys.argv) > 1 else "/etc/hosts"
sleep_s = float(sys.argv[2]) if len(sys.argv) > 2 else 0.0
max_opens = int(sys.argv[3]) if len(sys.argv) > 3 else 0  # 0 = unlimited

files = []  # keep references so they won't be GC'd/closed

i = 0
try:
    while True:
        f = open(path, "rb")
        files.append(f)
        i += 1

        if i % 100 == 0:
            print(f"opened={i} last_fd={f.fileno()} stored={len(files)}")

        if max_opens and i >= max_opens:
            print(f"reached max_opens={max_opens}; holding FDs open (Ctrl-C to exit)")
            while True:
                time.sleep(60)

        if sleep_s:
            time.sleep(sleep_s)

except KeyboardInterrupt:
    print(f"\nclosing {len(files)} files...")
    for f in files:
        try:
            f.close()
        except Exception:
            pass
    print("done.")
